const item = $input.first().json;
const body = item.body || item;

const phone = String(body.phone || body.from || body.sender || '').replace(/\D/g, '');
const senderName = body.senderName || body.pushName || body.name || 'Friend';
const rawMessage = (body.message || body.text || body.userMessage || '').trim();
const lower = rawMessage.toLowerCase();

// 1. Check for explicit mode switch commands
if (/^(!|\/)?(mode|switch)\s+(wholesale|oil|annamaliyar)/i.test(lower) || lower === 'switch to oil store') {
  return [{ json: { route: 'wholesale', modeSet: true, phone, senderName, message: rawMessage, prompt: 'Vanakkam! Annamaliyar Oil Store wholesale mode active.' } }];
}
if (/^(!|\/)?(mode|switch)\s+(restaurant|food|biryani|taj)/i.test(lower) || lower === 'switch to restaurant') {
  return [{ json: { route: 'restaurant', modeSet: true, phone, senderName, message: rawMessage, prompt: 'Vanakkam! Taj Hotel Biryani pre-order mode active.' } }];
}
if (/^(!|\/)?(mode|switch)\s+(dev|developer|solodeveloper|sales)/i.test(lower) || lower === 'switch to dev') {
  return [{ json: { route: 'dev', modeSet: true, phone, senderName, message: rawMessage, prompt: 'Vanakkam! SoloDeveloper.pro Sales OS mode active.' } }];
}

// 2. Numbered selection from welcome greeting
if (/^(1|one)$/i.test(lower)) {
  return [{ json: { route: 'wholesale', phone, senderName, message: 'I want to check wholesale oil rates and box inventory.', isDirectChoice: true } }];
}
if (/^(2|two)$/i.test(lower)) {
  return [{ json: { route: 'restaurant', phone, senderName, message: 'I want to check the Taj Hotel Biryani menu and pre-order token.', isDirectChoice: true } }];
}
if (/^(3|three)$/i.test(lower)) {
  return [{ json: { route: 'dev', phone, senderName, message: 'I want to build a website and AI WhatsApp automation.', isDirectChoice: true } }];
}

// 3. Keyword / Intent Classification (Zero-Token Regex)
const isOilWholesale = /\b(oil|gold winner|sunflower|tin|box|boxes|packet|litre|liter|wholesale|retailer|annamaliyar|lorry|loading|can|kann|price per box)\b/i.test(lower);
const isRestaurant = /\b(biryani|briyani|chicken|mutton|egg|parcel|taj hotel|taj|hotel|meals|food|table|lunch|dinner|token|spicy)\b/i.test(lower);
const isDevService = /\b(website|web app|next\.?js|crm|automation|bot|n8n|software|lead generation|proposal|demo|consultant|suresh)\b/i.test(lower);

if (isOilWholesale && !isRestaurant && !isDevService) {
  return [{ json: { route: 'wholesale', phone, senderName, message: rawMessage } }];
}
if (isRestaurant && !isOilWholesale && !isDevService) {
  return [{ json: { route: 'restaurant', phone, senderName, message: rawMessage } }];
}
if (isDevService && !isOilWholesale && !isRestaurant) {
  return [{ json: { route: 'dev', phone, senderName, message: rawMessage } }];
}

// 4. Default / Ambiguous Greeting ('Hi', 'Hello', 'Vanakkam')
// Sends Zero-Token Template Greeting Menu to eliminate ambiguity without calling Gemini LLM!
return [{
  json: {
    route: 'greeting',
    phone,
    senderName,
    message: rawMessage,
    greetingText: `வணக்கம் ${senderName}! Welcome to our Multi-Business AI Assistant! 👋\n\nஎங்களை தொடர்பு கொண்டமைக்கு நன்றி. உங்களுக்கு என்ன விபரம் தேவைப்படுகிறது?\n\n1️⃣ *அண்ணாமலையார் ஆயில் ஸ்டோர் (மாட்டுத்தாவணி)*\n   • Gold Winner Sunflower Oil மொத்த வியாபாரம் (Box & Tin Rates)\n   • Minimum 1 Box / 1 Tin Delivery\n\n2️⃣ *மதுரை தாஜ் ஹோட்டல்*\n   • சீரக சம்பா தம் பிரியாணி Pre-Orders\n   • Skip-the-line VIP Digital Token\n\n3️⃣ *SoloDeveloper.pro (Suresh Kumar)*\n   • High-Converting Websites & WhatsApp AI Automations\n   • n8n CRM Workflows from ₹8,999\n\n👉 *1, 2 அல்லது 3* என்று பதிலளிக்கவும் (அல்லது உங்கள் தேவையை நேரடியாக அனுப்பவும்)!`
  }
}];

